import ast, os, re, sys
sys.stdout.reconfigure(encoding="utf-8")
ROOT = "C:/Users/Георгий/AppData/Local/Temp/tmp.8wQt3IOS9q"
allpy, texts = [], {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d != ".git"]
    for f in fn:
        p = os.path.join(dp, f)
        r = os.path.relpath(p, ROOT).replace("\\", "/")
        if f.endswith(".py"):
            allpy.append(r)
        elif f.endswith((".md", ".sh", ".json", ".yml", ".yaml", ".ps1", ".toml", ".ini", ".cfg", ".txt", ".ts", ".js")):
            texts[r] = open(p, encoding="utf-8", errors="replace").read()
def is_test(r): return os.path.basename(r).startswith("test_")
scope = [r for r in allpy if not is_test(r) and (r.startswith(".claude/dispatcher/") or r.startswith(".claude/hooks/") or (r.startswith("tools/") and r.count("/") == 1))]
prod = [r for r in allpy if not is_test(r)]
tests = [r for r in allpy if is_test(r)]
trees = {}
def parse(r):
    if r not in trees:
        trees[r] = ast.parse(open(os.path.join(ROOT, r), encoding="utf-8").read(), r)
    return trees[r]
def refs(files):
    names, strs = {}, set()
    for r in files:
        for node in ast.walk(parse(r)):
            if isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load):
                key = node.id if isinstance(node, ast.Name) else node.attr
                names.setdefault(key, []).append(f"{r}:{node.lineno}")
            elif isinstance(node, ast.alias):
                names.setdefault(node.name.split(".")[-1], []).append(f"{r}:{node.lineno}")
            elif isinstance(node, ast.Constant) and isinstance(node.value, str):
                strs.add(node.value)
    return names, strs
pn, ps = refs(prod)
tn, _ = refs(tests)
print("scope files:", len(scope), "prod py:", len(prod), "test py:", len(tests))
defs, consts = [], []
for r in scope:
    t = parse(r)
    for node in ast.walk(t):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            defs.append((r, node.lineno, node.name, type(node).__name__))
    for node in t.body:
        if isinstance(node, ast.Assign):
            for tg in node.targets:
                if isinstance(tg, ast.Name): consts.append((r, node.lineno, tg.id))
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            consts.append((r, node.lineno, node.target.id))
print("== FUNC/CLASS DEFS with no prod refs ==")
docpat = lambda n: [k for k, v in texts.items() if re.search(r"(?<![\w])" + re.escape(n) + r"(?![\w])", v)]
for r, ln, n, kind in defs:
    if n.startswith("__"): continue
    if pn.get(n) or n in ps: continue
    tr = tn.get(n, [])
    d = docpat(n)
    print(f"{r}:{ln} {kind} {n} | test={len(tr)} {tr[:2]} | text={d[:3]}")
print("== MODULE CONSTS with no prod refs ==")
for r, ln, n in consts:
    if pn.get(n) or n in ps: continue
    tr = tn.get(n, [])
    d = docpat(n)
    print(f"{r}:{ln} CONST {n} | test={len(tr)} | text={d[:3]}")
EOF

