for r in prod:
    t = parse(r)
    def visit(node, encl):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            defs_prod.append((node.name, r, node.lineno))
            for ch in ast.iter_child_nodes(node):
                visit(ch, node.name)
            return
        if isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load):
            k = node.id if isinstance(node, ast.Name) else node.attr
            refs_by_name.setdefault(k, []).append((encl, r, node.lineno))
        elif isinstance(node, ast.alias):
            refs_by_name.setdefault(node.name.split(".")[-1], []).append((encl, r, node.lineno))
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            strs.add(node.value)
        for ch in ast.iter_child_nodes(node):
            visit(ch, encl)
    visit(t, "<module>")
alive = set(n for n, _, _ in defs_prod if n.startswith("__")) | set(strs)
changed = True
