import ast, os, re, sys
sys.stdout.reconfigure(encoding="utf-8")
ROOT = "C:/Users/Георгий/AppData/Local/Temp/tmp.8wQt3IOS9q"
allpy, texts = [], {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d != ".git"]
    for f in fn:
        p = os.path.join(dp, f); r = os.path.relpath(p, ROOT).replace("\\", "/")
        if f.endswith(".py"): allpy.append(r)
        elif f.endswith((".md", ".sh", ".json", ".yml", ".yaml", ".ps1", ".toml", ".ini", ".cfg", ".txt", ".js", ".ts")) or f == "run-hook.sh":
            texts[r] = open(p, encoding="utf-8", errors="replace").read()
is_test = lambda r: os.path.basename(r).startswith("test_")
prod = [r for r in allpy if not is_test(r)]
tests = [r for r in allpy if is_test(r)]
scope = [r for r in prod if (r.startswith(".claude/dispatcher/") or r.startswith(".claude/hooks/") or (r.startswith("tools/") and r.count("/") == 1))]
trees = {r: ast.parse(open(os.path.join(ROOT, r), encoding="utf-8").read(), r) for r in allpy}
# ---- B. argparse flags and whether their dest is ever read ----
attr_reads = {}   # attr name -> files (Load context)
str_consts = set()
for r in prod:
    for node in ast.walk(trees[r]):
        if isinstance(node, ast.Attribute) and isinstance(node.ctx, ast.Load):
            attr_reads.setdefault(node.attr, set()).add(r)
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            str_consts.add(node.value)
print("== B. argparse flags (dest read anywhere in prod py?) ==")
for r in scope + [x for x in prod if x not in scope and x.startswith("tools/")]:
    for node in ast.walk(trees[r]):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "add_argument":
            flags = [a.value for a in node.args if isinstance(a, ast.Constant) and isinstance(a.value, str)]
            longs = [f for f in flags if f.startswith("--")]
            dest = None; action = None
            for kw in node.keywords:
                if kw.arg == "dest" and isinstance(kw.value, ast.Constant): dest = kw.value.value
                if kw.arg == "action" and isinstance(kw.value, ast.Constant): action = kw.value.value
            if not longs: continue
            d = dest or longs[0][2:].replace("-", "_")
            reads = attr_reads.get(d, set())
            ext = [k for k, v in texts.items() if re.search(r"(?<![\w-])" + re.escape(longs[0]) + r"(?![\w-])", v)]
            if not reads:
                print(f"{r}:{node.lineno} flag={longs[0]} dest={d} action={action} | readers=NONE | text-mentions={ext[:3]}")
# ---- C. RPV_ env vars: context in py + mentions in other files ----
print("== C. RPV_* env vars ==")
parents = {}
for r in prod:
    for p in ast.walk(trees[r]):
        for ch in ast.iter_child_nodes(p):
            parents[id(ch)] = p
kinds = {}
